.plan-price{display:flex;align-items:baseline;gap:8px;margin:18px 0 26px}
.plan-price span{font-family:var(--font-head);font-size:2.6rem;font-weight:500}
.plan-price small{color:var(--ink-muted);font-size:.9rem}
