/* neon — generated by Orion. Plain CSS, yours to edit. */
:root{
  --bg:#0a0118;
  --bg-alt:#140430;
  --surface:rgba(236,72,153,0.07);
  --border:rgba(236,72,153,0.22);
  --ink:#fdf4ff;
  --ink-muted:#b39ccb;
  --accent:#ec4899;
  --accent-ink:#ffffff;
  --accent-soft:rgba(236,72,153,0.18);
  --radius:6px;
  --radius-lg:12px;
  --shadow:0 0 70px -30px rgba(236,72,153,0.8);
  --wrap:1160px;
  --pad:116px;
  --font-body:'Rajdhani', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --font-head:'Chakra Petch', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--font-body);font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4{font-family:var(--font-head);font-weight:700;letter-spacing:0em;line-height:1.08;margin:0}
h1{font-size:clamp(2.6rem,6.4vw,4.6rem)}
h2{font-size:clamp(2rem,4vw,3rem)}
h3{font-size:1.2rem;line-height:1.35}
p{margin:0}
ul,ol{margin:0;padding:0;list-style:none}
:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:4px}
.wrap{width:100%;max-width:var(--wrap);margin:0 auto;padding:0 24px}
.wrap.narrow{max-width:760px}
.section{padding:var(--pad) 0}
.section-head{max-width:660px;margin:0 0 56px}
.section-intro{color:var(--ink-muted);margin-top:16px;font-size:1.05rem}
.eyebrow{font-size:.78rem;letter-spacing:.16em;text-transform:uppercase;color:var(--accent);margin:0 0 20px;font-weight:600}
.lede{color:var(--ink-muted);font-size:clamp(1.05rem,1.8vw,1.28rem);max-width:56ch;margin:22px 0 0;line-height:1.6}

/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:14px 28px;border-radius:6px;font-weight:600;font-size:.98rem;border:1px solid transparent;transition:transform .25s cubic-bezier(.16,1,.3,1),background .25s,border-color .25s,opacity .25s;cursor:pointer;font-family:inherit}
.btn:hover{transform:translateY(-1px)}
.btn-primary{background:var(--accent);color:var(--accent-ink)}
.btn-primary:hover{opacity:.9}
.btn-outline{border-color:var(--border);color:var(--ink)}
.btn-outline:hover{border-color:var(--accent);color:var(--accent)}
.btn-ghost{color:var(--ink);background:var(--surface);border-color:var(--border)}

/* nav */
.nav{position:sticky;top:0;z-index:50;backdrop-filter:saturate(160%) blur(14px);background:color-mix(in srgb, var(--bg) 78%, transparent);border-bottom:1px solid var(--border)}
