.hero{position:relative;overflow:hidden;background-image:linear-gradient(rgba(236,72,153,0.22) 1px,transparent 1px),linear-gradient(90deg,rgba(236,72,153,0.22) 1px,transparent 1px);background-size:56px 56px;}
