.terminal-body{margin:0;padding:24px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.86rem;line-height:1.8;color:var(--ink-muted);white-space:pre-wrap}
.terminal-body .ok{color:var(--accent)}

