.ico{width:20px;height:20px}
.bento{display:grid;grid-template-columns:repeat(6,1fr);gap:22px}
.bento-1{grid-column:span 4}
.bento-2{grid-column:span 2}
.bento-3{grid-column:span 2}
.bento-4{grid-column:span 2}
