.hero{position:relative;overflow:hidden;background-image:radial-gradient(520px 320px at 12% 0%, rgba(34,211,238,0.15), transparent 65%),radial-gradient(620px 380px at 88% 12%, rgba(34,211,238,0.15), transparent 62%);}
.hero-inner{padding:clamp(80px,12vw,148px) 24px clamp(60px,8vw,96px);text-align:center;display:flex;flex-direction:column;align-items:center}
.hero-centered .lede{margin-inline:auto;text-align:center}
