  --ink-muted:#7fa896;
  --accent:#00ff9d;
  --accent-ink:#04140e;
  --accent-soft:rgba(0,255,157,0.14);
  --radius:4px;
  --radius-lg:8px;
  --shadow:0 0 60px -30px rgba(0,255,157,0.5);
  --wrap:1040px;
  --pad:104px;
  --font-body:'JetBrains Mono', ui-monospace, monospace;
  --font-head:'JetBrains Mono', ui-monospace, monospace;
