.faq-list{display:grid;gap:0;border-top:1px solid var(--border)}
.faq-item{border-bottom:1px solid var(--border);padding:22px 0}
.faq-item summary{cursor:pointer;font-family:var(--font-head);font-size:1.05rem;font-weight:700;list-style:none;display:flex;justify-content:space-between;gap:20px}
