.hero-media.wide{margin-top:72px}
.hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:64px;align-items:center;padding-top:clamp(72px,10vw,124px);padding-bottom:clamp(72px,10vw,124px)}
