  --accent-ink:#ffffff;
  --accent-soft:rgba(224,87,143,0.13);
  --radius:18px;
  --radius-lg:32px;
  --shadow:0 24px 70px -46px rgba(190,90,130,0.4);
  --wrap:1080px;
  --pad:112px;
