.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:14px 28px;border-radius:20px;font-weight:600;font-size:.98rem;border:1px solid transparent;transition:transform .25s cubic-bezier(.16,1,.3,1),background .25s,border-color .25s,opacity .25s;cursor:pointer;font-family:inherit}
