  .alt-row.reverse .alt-copy{order:0}
  .grid-3,.grid-4,.gallery-grid,.step-list,.stat-grid{grid-template-columns:repeat(2,1fr)}
  .bento{grid-template-columns:repeat(2,1fr)}
