.nav-links a{color:var(--ink-muted);font-size:.94rem;transition:color .2s;text-transform:uppercase;letter-spacing:.12em;font-size:.76rem}
.nav-links a:hover{color:var(--ink)}
.nav-center .nav-inner{display:grid;grid-template-columns:1fr auto 1fr}
.nav-center .nav-right{justify-content:flex-end}
.brand-center{text-align:center}
.nav-toggle{display:none;flex-direction:column;gap:5px;background:none;border:0;padding:8px;cursor:pointer}
