.hero{position:relative;overflow:hidden;background-image:linear-gradient(rgba(0,255,157,0.18) 1px,transparent 1px),linear-gradient(90deg,rgba(0,255,157,0.18) 1px,transparent 1px);background-size:56px 56px;}
.hero-inner{padding:clamp(80px,12vw,148px) 24px clamp(60px,8vw,96px);text-align:center;display:flex;flex-direction:column;align-items:center}
