.logo-row{display:flex;flex-wrap:wrap;justify-content:center;gap:16px 56px}
.logo-row li{font-family:var(--font-head);font-weight:600;font-size:1.06rem;color:var(--ink);opacity:.55;transition:opacity .3s}
